"""Normalize evidence paths without changing third-party source files."""
import os, pathlib, re
ROOT = pathlib.Path(__file__).resolve().parent.parent

def normalize(text):
    prefixes = [(str(ROOT), '$ROOT'), (str(pathlib.Path.home()), '$HOME')]
    if os.environ.get('ACCEPTANCE_FORMAT'):
        prefixes.insert(0, (os.environ['ACCEPTANCE_FORMAT'], '$ACCEPTANCE_FORMAT'))
    for prefix, replacement in prefixes:
        text = text.replace(prefix, replacement)
    for pattern, replacement in [
        (r'/Applications/[^\s"\n]*?\.app/Contents/Developer', '$TOOLCHAIN'),
        (r'/Library/Developer/CommandLineTools', '$TOOLCHAIN'),
        (r'(?:/private)?/var/folders/[^\s"\n:]+', '$TMP'),
        (r'/System/Library/', '$SYSTEM/'),
        (r'/opt/homebrew/', '$PACKAGE_MANAGER/'),
        (r'/usr/', '$USR/'),
        (r'(?:/private)?/tmp/', '$TMP/'),
        ('/'+'Users'+r'/[^/\s"\n]+', '$HOME'),
    ]:
        text = re.sub(pattern, replacement, text)
    return text

def normalize_tree(root):
    for path in root.rglob('*'):
        if not path.is_file() or path.is_symlink():
            continue
        try:
            raw = path.read_text()
        except (UnicodeError, OSError):
            continue
        clean = normalize(raw)
        if clean != raw:
            path.write_text(clean)
